// Where a project stands in Spec Kit's workflow, the step that comes next, and the autopilot's rules. Pure: register.tsx hands in the snapshot.

import type { Autopilot, IdeaBrief, Ledger, Snapshot, Task } from '../types'
import { designChangeLine, designDue, designNote, designPrompt, designToReview } from './design'
import { fingerprint, specFingerprint } from './rules'
import { evaluate, speckitCommand } from './xref'

export type Phase =
  | 'setup'
  | 'integration'
  | 'validate'
  | 'shape'
  | 'constitution'
  | 'specify'
  | 'clarify'
  | 'review'
  | 'plan'
  | 'design'
  | 'tasks'
  | 'revise'
  | 'map'
  | 'analyze'
  | 'remediate'
  | 'checklists'
  | 'implement'
  | 'repair'
  | 'converge'
  | 'verify'
export type Step = {
  phase: Phase
  command: string | null
  why: string
  notes: string[]
  /** Set when only the person can take this step: what they have to do. */
  needsUser: string | null
  /** What the step hands Claude instead of "run <command>", for steps that are no single command. */
  prompt?: string
  /**
   * What the step settles: an approval only the person gives (`spec`, `plan`, `checklists`), or a checkpoint the
   * autopilot records when it hands the step over (`analyze`, `converge`); the value is the fingerprint it holds for.
   */
  approve?: { key: string; value: string }
  /** The request a revise step folds into the spec: handing the step over takes it off the list. */
  resolves?: string
}

/** Where the autopilot stops for the person: the spec always (unless none), the plan and the design when named. */
export type Review = 'spec' | 'spec+plan' | 'spec+design' | 'spec+plan+design' | 'none'
export const REVIEWS: Review[] = ['spec+design', 'spec', 'spec+plan', 'spec+plan+design', 'none']
export const gatesOf = (review: Review) => ({ spec: review !== 'none', plan: review.includes('plan'), design: review.includes('design') })

/** What the workflow reads beyond the snapshot: the review option, the persistence model, the last test run. */
export type Flow = {
  review: Review
  /** Validate and Shape for a new project's first feature (both on unless switched off). */
  validate?: boolean
  shape?: boolean
  /** The design step for a feature with a user interface (on unless switched off). */
  design?: boolean
  lastTest?: Autopilot['lastTest']
  repairs?: number
  /** The last analysis found something to fix: the next step applies its remediation. */
  remediate?: boolean
}

const INIT = 'init --here --force --non-interactive --integration claude'
export const MAX_REPAIRS = 3

/** How Spec Kit's CLI runs here: installed, or through uvx without installing. */
export const specifyCli = (snap: Snapshot) => (snap.tools.specify ? 'specify' : `uvx --from 'specify-cli>=1.1,<2' specify`)

/** What a spec change sets off (docs/research.de.md §5), as the constitution names it: `Persistence model: living`. */
export type Persistence = 'flow-back' | 'flow-forward' | 'living'
export function persistenceModel(constitutionMd: string | null): Persistence {
  const m = /persistence(?:\s+model)?\s*[:=-]\s*\**\s*(flow[- ]back|flow[- ]forward|living(?:\s+spec)?)/i.exec(constitutionMd ?? '')
  const value = m?.[1]?.toLowerCase().replace(' ', '-') ?? 'flow-back'
  return value.startsWith('living') ? 'living' : value === 'flow-forward' ? 'flow-forward' : 'flow-back'
}

/** What a backticked span must start with to be a command rather than a package or a tool name (`jest-expo`). */
const RUNNER = /^(?:npm|npx|pnpm|yarn|bun|bunx|deno|node|pytest|python3?|uv|poetry|cargo|go|flutter|dart|make|mvn|gradle|\.\/gradlew|dotnet|bundle|rake|rspec|mix|swift|xcodebuild|vitest|jest|phpunit|composer)(?=\s|$)/

/** The test command plan.md's `**Testing**:` line implies: a backticked command as written, else the framework's usual one. */
export function testCommandFrom(planMd: string | null): string | null {
  const line = /^\*\*Testing\*\*:\s*(.+)$/m.exec(planMd ?? '')?.[1]?.trim()
  if (!line || /NEEDS CLARIFICATION|^\[/.test(line)) return null
  const ticked = [...line.matchAll(/`([^`]+)`/g)].map(m => m[1]!.trim()).find(t => RUNNER.test(t))
  if (ticked) return ticked
  const known: [RegExp, string][] = [
    [/vitest/i, 'npx vitest run'],
    [/jest/i, 'npx jest'],
    [/playwright/i, 'npx playwright test'],
    [/pytest/i, 'pytest'],
    [/cargo/i, 'cargo test'],
    [/\bgo test|\bgo\b/i, 'go test ./...'],
    [/flutter/i, 'flutter test'],
    [/dart/i, 'dart test'],
    [/rspec/i, 'bundle exec rspec'],
    [/npm test|node:test|mocha/i, 'npm test'],
  ]
  return known.find(([re]) => re.test(line))?.[1] ?? null
}

/**
 * The project's own test script, when package.json has one: what `npm test` runs is what the project means by
 * "the tests". A watch-mode script would never end, and npm's placeholder fails on purpose: neither counts.
 */
export function testScriptCommand(packageJson: string | null, lockfiles: { pnpm: boolean; yarn: boolean; bun: boolean }): string | null {
  let script: unknown
  try {
    script = (JSON.parse(packageJson ?? '') as { scripts?: Record<string, unknown> }).scripts?.test
  } catch {
    return null
  }
  if (typeof script !== 'string' || !script.trim() || /no test specified|--watch(?:All)?\b(?!=false)/.test(script)) return null
  return lockfiles.pnpm ? 'pnpm test' : lockfiles.yarn ? 'yarn test' : lockfiles.bun ? 'bun run test' : 'npm test'
}

/** The line of a test run that says what failed (`Test Suites: 1 failed, 27 passed`), not its last words (`Ran all test suites.`). */
export function failureLine(output: string): string {
  const lines = output.split('\n').map(l => l.trim()).filter(Boolean)
  return [...lines].reverse().find(l => /\b(fail(ed|ing|ures?)?|error|✕|FAIL)\b/i.test(l)) ?? lines.at(-1) ?? ''
}

/** Whether a test run failed to start rather than failed: the shell's "command not found" and "not executable". */
export const couldNotRun = (exitCode: number, output: string) => exitCode === 126 || exitCode === 127 || /command not found|not recognized as an internal or external command/i.test(output.slice(-2000))

/** Where the spec stands with the person: approved for this text, approved for an older one, or never reviewed. */
export function specReview(snap: Snapshot, ledger: Ledger): 'approved' | 'changed' | 'unreviewed' {
  if (!snap.spec) return 'unreviewed'
  if (!ledger.approvals.spec) return 'unreviewed'
  return ledger.approvals.spec === specFingerprint(snap.spec) ? 'approved' : 'changed'
}

/** tasks.md's `##` phases in order, each with its tasks done and in all, and which one is open now. */
export type TaskPhase = { title: string; done: number; total: number }
export function taskPhases(tasks: Task[]): { phases: TaskPhase[]; current: number } {
  const phases: TaskPhase[] = []
  for (const t of tasks) {
    const title = t.phase || 'Tasks'
    let p = phases.find(x => x.title === title)
    if (!p) phases.push((p = { title, done: 0, total: 0 }))
    p.total += 1
    if (t.done) p.done += 1
  }
  return { phases, current: phases.findIndex(p => p.done < p.total) }
}

/** A phase's number as tasks.md writes it (`Phase 3: …` is 3, even with no Phase 2), else its place in the file. */
export const phaseNumber = (title: string, index: number) => Number(/^Phase\s+(\d+)/i.exec(title)?.[1] ?? index + 1)

/** `Phase 3: User Story 1 – Inspiration für den Moment (Priority: P1) 🎯 MVP` → `US1 Inspiration für den Moment (P1) MVP`. */
export function phaseLabel(title: string): string {
  return title
    .replace(/^Phase\s+\d+\s*[:.–-]\s*/i, '')
    .replace(/User Story\s+(\d+)\s*[–—:-]\s*/i, 'US$1 ')
    .replace(/\(Priority:\s*(P\d+)\)/i, '($1)')
    .replace(/🎯\s*/g, '')
    .trim()
}

/** The first `##` phase of tasks.md that still has an open task: what one implement step covers. */
export const openPhase = (tasks: Task[]) => tasks.find(t => !t.done)?.phase || null

/** A fingerprint of the task list that ignores the checkboxes: converge changes it, implement does not. */
export const tasksFingerprint = (tasks: Task[]) => fingerprint(tasks.map(t => `${t.id} ${t.text}`).join('\n'))

/** The open checklist items of a feature's `checklists/*.md`, by file. */
export function openChecklistItems(files: Record<string, string>): { file: string; open: number }[] {
  return Object.entries(files)
    .map(([file, text]) => ({ file, open: (text.match(/^\s*[-*]\s*\[ \]/gm) ?? []).length }))
    .filter(f => f.open > 0)
}

export function nextStep(snap: Snapshot, ledger: Ledger, idea: string | null = null, flow: Flow = { review: 'spec' }): Step {
  const notes: string[] = []
  const xref = snap.extensions.includes('xref')
  const has = (name: string) => (snap.commands ?? []).includes(name)
  const step = (phase: Phase, command: string | null, why: string, needsUser: string | null = null, extra: Partial<Step> = {}): Step => ({ phase, command, why, notes, needsUser, ...extra })

  // Setting Spec Kit up writes into the repository: that is always the person's call, never the autopilot's.
  if (!snap.initialized) {
    if (!snap.tools.specify && !snap.tools.uvx) {
      return step('setup', null, 'Spec Kit is not set up, and neither the specify CLI nor uvx is on this machine.', 'Install uv (https://docs.astral.sh/uv/) or the specify CLI (pipx install specify-cli).')
    }
    return snap.folder === 'empty'
      ? step('setup', `${specifyCli(snap)} ${INIT}`, 'This folder is empty: a new app, project or problem can start here with Spec Kit.', 'Tell me what you want to build (an app, a project, a problem): I set Spec Kit up for it and write the spec in your words.')
      : step('setup', `${specifyCli(snap)} ${INIT}`, 'This folder has code, but no Spec Kit yet (no .specify/).', 'Say "set up Spec Kit here" to bring this project under Spec Kit, or press Set up Spec Kit in the pane.')
  }
  if (!snap.claudeIntegration) {
    return step('integration', `${specifyCli(snap)} integration install claude`, "Spec Kit is set up, but not for Claude Code: its /speckit-* skills are missing.", 'Say "add the Claude integration", or press Add Claude integration in the pane.')
  }
  // A new project's first feature starts at the idea: researched (Validate) and shaped with the person (Shape)
  // before the constitution and the spec are written from it.
  const greenfield = snap.folder === 'empty' && snap.features.length === 0 && (!snap.featureDir || !snap.spec)
  if (greenfield && flow.validate !== false) {
    const brief = snap.ideaBrief
    const decided = brief && snap.ideaDecision?.fingerprint === brief.fingerprint ? snap.ideaDecision.decision : null
    if (!brief && !idea) {
      return step('validate', null, 'No idea yet: it is researched before it becomes a spec.', 'Describe what you want to build, in your own words: I research it first, then we shape and specify it.')
    }
    if (!brief) {
      return step('validate', null, 'The idea is known: research it before it becomes a spec.', null, { prompt: validatePrompt(idea!) })
    }
    if (decided === 'drop') return step('validate', null, `You dropped the idea "${brief.title}".`, 'You dropped this idea: Reopen it in the pane, or start a new idea there.')
    if (decided !== 'build') {
      return step('review', null, `The idea brief is written: ${brief.oneLiner ?? brief.title}${brief.score !== null ? ` (score ${brief.score}/5, ${brief.recommendation ?? 'no recommendation'})` : ''}.`,
        'Read the idea brief, then press Build, Sharpen or Drop in the pane.', { approve: { key: 'idea', value: brief.fingerprint } })
    }
  }
  if (greenfield && flow.shape !== false && !snap.productBrief) {
    return step('shape', null, 'Before the spec: settle with the person what the first version is (scope, platforms, language, design, data).', null, { prompt: SHAPE_PROMPT })
  }
  if (!snap.constitution || snap.constitution.principles.length === 0) {
    if (snap.ideaBrief || snap.productBrief) notes.push(BRIEFS_NOTE)
    return step('constitution', speckitCommand(snap, 'constitution'), 'The constitution is missing or still the template.')
  }
  if ((!snap.featureDir || !snap.spec) && snap.commits === false) {
    // Spec Kit opens a branch per feature only in a repository with a commit to branch from.
    return step('setup', null, 'The repository has no commit yet: Spec Kit opens a branch per feature only from one.', 'Make the first commit: press First commit in the pane, or ask for it.')
  }
  if (!snap.featureDir || !snap.spec) {
    if (snap.ideaBrief || snap.productBrief) notes.push(BRIEFS_NOTE)
    return idea
      ? step('specify', `${speckitCommand(snap, 'specify')} ${idea}`, 'No feature yet; the person has said what to build.')
      : step('specify', speckitCommand(snap, 'specify'), 'No feature yet: describe what to build.', 'Describe the feature you want built; your own words become the spec.')
  }

  const spec = snap.spec
  if (snap.commits === false) notes.push('No commit yet: Spec Kit cannot branch per feature, and commit per task and the GitHub Action need commits (First commit in the pane).')
  const unclear = spec.reqs.filter(r => r.needsClarification).map(r => r.id)
  const specFp = specFingerprint(spec)
  // The one review: where the idea becomes the contract. A project planned before 0.4 counts as reviewed until its spec changes.
  const specApproved = ledger.approvals.spec ? ledger.approvals.spec === specFp : snap.hasPlan
  const gates = gatesOf(flow.review)
  if (!snap.hasPlan && unclear.length) return step('clarify', speckitCommand(snap, 'clarify'), `${unclear.join(', ')} still marked NEEDS CLARIFICATION; settle them before planning.`)
  if (gates.spec && !specApproved) {
    return step('review', null, `The spec of ${snap.featureDir} is written: ${spec.reqs.filter(r => r.kind === 'FR').length} requirements, ${spec.outOfScope.length} out of scope, ${spec.assumptions.length} assumptions.`,
      'Review the spec against your words, then press Approve spec in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'spec', value: specFp } })
  }
  if (!snap.hasPlan) return step('plan', speckitCommand(snap, 'plan'), 'The spec is written; plan.md is missing.')
  if (gates.plan && snap.planFingerprint) {
    const planApproved = ledger.approvals.plan ? ledger.approvals.plan === snap.planFingerprint : snap.tasks.length > 0
    if (!planApproved) {
      return step('review', null, `The plan of ${snap.featureDir} is written.`, 'Review plan.md, then press Approve plan in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'plan', value: snap.planFingerprint } })
    }
  }
  // A feature people look at gets its look before its tasks: a design system and a mock per screen, then the person's eye.
  if (flow.design !== false && snap.ui && snap.tasks.length === 0) {
    if (designDue(snap.design)) {
      return step('design', null, `${snap.featureDir} has a user interface: settle its look before the tasks (DESIGN.md and a mock per screen).`, null, { prompt: designPrompt(snap) })
    }
    const design = snap.design!
    if (gates.design && designToReview(design) && ledger.approvals.design !== design.fingerprint) {
      const screens = design.screens?.length ?? 0
      return step('review', null, `The design of ${snap.featureDir} is drafted: ${screens} screen${screens === 1 ? '' : 's'}${designChangeLine(design)}.`,
        'Look at DESIGN.md and the mocks (/xref web or Mocks in the pane opens them in the browser), then press Approve design in the pane (or /xref approve); tell me what to change otherwise.', { approve: { key: 'design', value: design.fingerprint } })
    }
  }
  const drawn = snap.featureDir && snap.design?.screens?.length ? designNote(snap.featureDir) : null
  if (unclear.length) notes.push(`${unclear.join(', ')} still marked NEEDS CLARIFICATION (${speckitCommand(snap, 'clarify')}).`)
  if (snap.tasks.length === 0) {
    if (drawn) notes.push(drawn)
    return step('tasks', speckitCommand(snap, 'tasks'), 'The plan is written; tasks.md is missing.')
  }

  // A request beyond the spec reaches the spec before more code does; a contradiction is always the person's.
  const changes = ledger.semantic?.changes ?? []
  const contradiction = changes.find(c => c.kind === 'contradicts')
  if (contradiction) return step('revise', null, `"${contradiction.text}" contradicts the spec.`, `Your request "${contradiction.text}" contradicts the spec: keep the spec, or change it (To spec in the pane).`)
  const extension = changes.find(c => c.kind === 'extends')
  if (extension) {
    if (snap.persistence === 'flow-forward') return step('revise', null, `"${extension.text}" goes beyond the spec.`, `You asked for "${extension.text}", which the spec does not cover: fold it into the spec (To spec), or make it a task (As task).`)
    const revise = xref && has('xref-revise') ? speckitCommand(snap, 'xref.revise') : speckitCommand(snap, 'clarify')
    return step('revise', `${revise} The user asked during implementation: "${extension.text}". Fold it into the spec, new requirements under new ids.`, `"${extension.text}" goes beyond the spec; the spec follows the request (${snap.persistence ?? 'flow-back'}).`, null, { resolves: extension.text })
  }

  const report = evaluate(snap, ledger)
  if (report.level === 'red' || report.level === 'yellow') notes.push(`Drift ${report.level}: ${report.findings[0]?.text ?? ''}`)
  const mapped = Object.values(ledger.requirements).some(r => r.tasks.length > 0)
  const uncovered = report.uncovered.filter(id => !unclear.includes(id))
  if (uncovered.length && !mapped) {
    return step('map', xref ? speckitCommand(snap, 'xref.map') : '/xref map', `${uncovered.join(', ')} name no task yet; map requirements to tasks once.`)
  }
  const open = snap.tasks.filter(t => !t.done)
  const started = snap.tasks.some(t => t.done)
  // analyze before the first implement, and again after every change to the spec.
  if (open.length && has('analyze') && (ledger.checkpoints.analyze ? ledger.checkpoints.analyze !== specFp : !started)) {
    return step('analyze', speckitCommand(snap, 'analyze'), started ? 'The spec changed since the last analysis: check spec, plan and tasks against each other.' : 'Before the first task: check spec, plan and tasks against each other.', null, { approve: { key: 'analyze', value: specFp } })
  }
  // An analysis that found something is followed through: its fixes go in before the next task does.
  if (open.length && (flow.remediate || ledger.checkpoints.remediate === 'due')) {
    return step('remediate', null, 'The analysis found inconsistencies: apply its remediation before the next task.', null, {
      prompt: [
        `Apply the remediation the last ${speckitCommand(snap, 'analyze')} proposed, in this step and without asking whether to.`,
        'Edit tasks.md, plan.md, data-model.md and spec.md where the findings point. Keep every existing id; new tasks get the next free T### in the phase they belong to, new requirements the next free FR-###. Check nothing off.',
        'Decide what the person left open and record it as an assumption. A product decision only the person can make (scope, a user-facing behaviour the spec leaves open) goes to mcp__speckit-xref__ask, with options and the stories it blocks.',
      ].join('\n'),
    })
  }
  if (flow.lastTest && !flow.lastTest.ok) {
    if ((flow.repairs ?? 0) > MAX_REPAIRS) {
      return step('repair', null, `The tests still fail after ${MAX_REPAIRS} repairs.`, `The tests still fail after ${MAX_REPAIRS} attempts: look at the failure in the pane and decide how to go on.`)
    }
    return step('repair', snap.testCommand, `The tests fail (repair ${Math.max(1, flow.repairs ?? 0)} of ${MAX_REPAIRS}).`, null, {
      prompt: `The tests fail. Run \`${snap.testCommand}\`, find the cause and fix the code (not the tests, unless a test contradicts the spec). Do not check off new tasks in this step.\nLast output:\n${flow.lastTest.output.slice(-1500)}`,
    })
  }
  if (open.length) {
    const checklists = snap.checklists ?? []
    const listFp = fingerprint(checklists.map(c => `${c.file}:${c.open}`).join('\n'))
    if (checklists.length && !started && ledger.approvals.checklists !== listFp) {
      return step('checklists', null, `${checklists.reduce((n, c) => n + c.open, 0)} checklist items are open (${checklists.map(c => c.file).join(', ')}).`, 'Checklist items are open: complete them, or press Proceed anyway in the pane (/xref approve).', { approve: { key: 'checklists', value: listFp } })
    }
    // One phase per step (Spec Kit's own advice for larger features): the budget and the stall check then measure real work.
    const phase = snap.phase
    const command = speckitCommand(snap, 'implement')
    if (drawn) notes.push(drawn)
    const ids = (phase ? open.filter(t => t.phase === phase) : open).map(t => t.id)
    return step('implement', command, `${open.length} of ${snap.tasks.length} tasks open; next ${open[0]!.id}.`, null, {
      prompt: phase
        ? `Run ${command} now through the Skill tool, scoped by its argument to one phase: "Only the phase '${phase}' (${ids.join(', ')}); stop when it is done." Carry that phase through.`
        : undefined,
    })
  }
  const tasksFp = snap.tasksFingerprint || tasksFingerprint(snap.tasks)
  if (has('converge') && ledger.checkpoints.converge !== tasksFp) {
    return step('converge', speckitCommand(snap, 'converge'), 'Every task is checked: find the work the tasks missed.', null, { approve: { key: 'converge', value: tasksFp } })
  }
  if (xref) return step('verify', speckitCommand(snap, 'xref.check'), 'Every task is checked: check the code against the spec.')
  // Without the extension there is no command the model can run: it checks by itself, and the mod's intent check follows.
  return step('verify', null, 'Every task is checked: check the code against the spec.', null, {
    prompt: [
      "Check the code against the spec and against the person's own words (the spec's Input), by yourself: /xref check is the person's command, not one you can run.",
      'For each requirement name the code and the test that prove it. For each point the person made, say whether the app does it.',
      "Whatever is missing or differs becomes a new task at the end of tasks.md under '## Phase N: Verification' (the next free T### ids). Then end your turn.",
    ].join('\n'),
  })
}

/** What Validate is handed: the person's words and the skill that researches them. */
export function validatePrompt(idea: string): string {
  return [
    'Validate the idea before it becomes a spec, with the speckit-xref:validate skill: research it (the speckit-xref:idea-researcher agent does the web research where web tools are there) and write .specify/memory/idea-brief.md in the format the skill gives.',
    `The idea, in the person's words: "${idea}"`,
    'Never invent a source: an alternative without a URL you fetched is marked (unverified). Without web tools, say so in the brief. Do not write a **Decision** line: Build, Sharpen or Drop is the person\'s call.',
  ].join('\n')
}

const SHAPE_PROMPT = [
  'Shape the first version with the person before the spec is written, with the speckit-xref:shape skill.',
  'Ask in the AskUserQuestion dialog only what the idea and .specify/memory/idea-brief.md leave open: which user stories make the first version (the MVP cut), platforms, language and internationalisation, the design direction (mood, references, dark mode, accessibility), data and accounts. At most 4 questions a round, the recommended answer first.',
  "Write .specify/memory/product-brief.md with '## Decisions (the person's)' and '## Assumptions (Claude's)'. Where nobody can answer (no dialog), record each point as an assumption.",
].join('\n')

const BRIEFS_NOTE =
  "Use .specify/memory/idea-brief.md and .specify/memory/product-brief.md: the decisions in them are the person's (write them as decided, never as assumptions), the brief's success measures become SC-###, its riskiest assumption is what the first user story tests, and its differentiation belongs in the constitution."

/** Reads an idea brief (`.specify/memory/idea-brief.md`, the format the validate skill writes). */
export function parseIdeaBrief(markdown: string): IdeaBrief {
  const field = (name: string) => new RegExp(`^\\*\\*${name}\\*\\*:\\s*(.+)$`, 'mi').exec(markdown)?.[1]?.trim() ?? null
  const section = (name: RegExp) => {
    const out: string[] = []
    let inside = false
    for (const line of markdown.split('\n')) {
      const h = /^##\s+(.+)$/.exec(line)
      if (h) {
        inside = name.test(h[1] ?? '')
        continue
      }
      const item = inside ? /^\s*(?:[-*]|\d+\.)\s+(.+)$/.exec(line) : null
      if (item) out.push(item[1]!.trim())
    }
    return out
  }
  const rec = field('Recommendation')?.toLowerCase().match(/build|sharpen|drop/)?.[0] as IdeaBrief['recommendation'] | undefined
  const score = Number(/([\d.]+)\s*\/\s*5/.exec(field('Score') ?? '')?.[1])
  const research = field('Research')
  return {
    title: /^#\s+(?:Idea Brief:\s*)?(.+)$/m.exec(markdown)?.[1]?.trim() ?? 'Idea',
    oneLiner: field('One-liner'),
    recommendation: rec ?? null,
    score: Number.isFinite(score) ? score : null,
    research: !!research && !/^none\b/i.test(research),
    alternatives: section(/^alternatives/i).map(line => {
      const link = /^\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)\s*[:–—-]?\s*(.*)$/.exec(line)
      if (link && !/\(unverified\)/i.test(line)) return { name: link[1]!, url: link[2]!, note: link[3] ?? '', verified: true }
      const [name, ...rest] = line.replace(/\[([^\]]+)\]\([^)]*\)/, '$1').split(/:\s+/)
      return { name: name!.replace(/\s*\(unverified\)\s*/i, '').trim(), url: null, note: rest.join(': '), verified: false }
    }),
    risks: section(/riskiest/i),
    kill: section(/^kill/i),
    success: section(/^success/i),
    fingerprint: fingerprint(markdown.split('\n').filter(l => !/^\*\*Decision\*\*:/i.test(l)).join('\n')),
  }
}

/** The step as one line, as the pane, /xref and the note on each prompt show it. */
export const stepLine = (s: Step) => (s.command ? `${s.command} · ${s.why}` : s.why)

export const idleAutopilot = (): Autopilot => ({
  on: false,
  paused: null,
  steps: 0,
  max: 25,
  last: null,
  stalls: 0,
  lastPhase: null,
  idea: null,
  repairs: 0,
  lastTest: null,
  startedAt: null,
  costAtStart: 0,
  night: false,
  scope: null,
  remediate: false,
  remediations: 0,
  testNote: null,
})

/** Whether the person's next words are the idea to specify: the autopilot waits on them for exactly that. */
export const takesIdea = (step: Step, snap: Snapshot) =>
  step.phase === 'specify' || (step.phase === 'validate' && step.needsUser !== null && !snap.ideaBrief) || (step.phase === 'setup' && snap.folder === 'empty' && step.command !== null)

/** What the model reads beside the person's prompt while the autopilot waits before Spec Kit is there. */
export function setupNote(step: Step, snap: Snapshot): string {
  const lines = [`speckit-xref · autopilot waiting · ${step.why}`]
  if (step.phase === 'setup' && step.command && snap.folder === 'empty') {
    lines.push(`If this message says what to build, set Spec Kit up now with the speckit-xref:speckit skill (\`${step.command}\`); the autopilot then goes on with the constitution and the spec in the person's words.`)
  } else if (step.phase === 'setup' && step.command) {
    lines.push(`Set Spec Kit up (speckit-xref:speckit skill, \`${step.command}\`) only if this message asks for it; otherwise leave the repository as it is.`)
  } else if (step.phase === 'integration') {
    lines.push(`Run \`${step.command}\` only if this message asks for it.`)
  }
  return lines.join('\n')
}

/** What has to change between two autopilot steps for the run to count as moving. */
export function progressKey(snap: Snapshot, ledger: Ledger): string {
  const report = evaluate(snap, ledger)
  const mapped = Object.values(ledger.requirements).filter(r => r.tasks.length > 0).length
  return [
    snap.initialized,
    snap.claudeIntegration,
    snap.constitution?.principles.length ?? 0,
    snap.featureDir ?? '-',
    snap.spec?.reqs.length ?? 0,
    snap.spec?.reqs.filter(r => r.needsClarification).length ?? 0,
    snap.hasPlan,
    !!snap.ideaBrief,
    !!snap.productBrief,
    snap.design ? `${snap.design.system}:${snap.design.screens?.length ?? '-'}` : '-',
    `${report.done}/${report.tasks}`,
    snap.tasksFingerprint ?? '-',
    mapped,
    report.level,
    Object.values(report.levels).join('/'),
    ledger.semantic?.at ?? '-',
    JSON.stringify(ledger.checkpoints),
  ].join('|')
}

/** The rules the autopilot gives the model with every step it hands over. */
export const AUTONOMY_RULES = [
  'Autopilot is on. Carry the step through without asking whether to continue: when you end your turn, the autopilot moves on by itself.',
  'Decide what the person left open, from the spec, the constitution and the repository, and record those choices as assumptions in the artifact you write.',
  'Stop only for what only the person can decide: the product idea, a [NEEDS CLARIFICATION] question, a conflict between their request and the spec, anything destructive or irreversible, credentials or payments. Then call mcp__speckit-xref__ask with the question (and the user stories it blocks, if any); if it answers with the person\'s choice, go on with it, otherwise put the question in your answer and end your turn.',
]

/** The prompt the autopilot submits for one step. */
export function autopilotPrompt(step: Step, n: number, max: number, context: string | null): string {
  return [
    `[speckit-xref autopilot · step ${n}/${max}] ${step.phase}: ${step.why}`,
    step.prompt ?? `Run ${step.command} now: invoke it through the Skill tool and carry it through.`,
    ...step.notes.map(note => `Note: ${note}`),
    '',
    ...AUTONOMY_RULES,
    ...(context ? ['', context] : []),
  ].join('\n')
}

/** Whether a model's answer ends on a question, the one case the autopilot asks a small model about. */
export const endsWithQuestion = (answer: string) => /\?["')\]*_\s]*$/.test(answer.trim().slice(-400))

/** The labels for that question; the first means stop. A "shall I continue?" is the second. */
export const QUESTION_LABELS = ['needs a decision only the person can make', 'asks only whether to continue, or reports progress'] as const

/** The phase strip: `✓setup ✓const ✓spec ✓plan ✓tasks ▶impl 7/8 ·verify`; `◌spec` is a spec passed without your review. */
export function phaseStrip(snap: Snapshot, step: Step, unreviewed = false): string {
  // The idea column shows only for a project that started at an idea (Validate, Shape).
  const ideas = !!snap.ideaBrief || !!snap.productBrief || step.phase === 'validate' || step.phase === 'shape'
  // The design column shows for a feature with screens, and while its design is drawn or reviewed.
  const drawn = !!snap.design?.screens?.length || step.phase === 'design' || step.approve?.key === 'design'
  const order: [string, Phase[]][] = [
    ['setup', ['setup', 'integration']],
    ...(ideas ? [['idea', ['validate', 'shape']] as [string, Phase[]]] : []),
    ['const', ['constitution']],
    ['spec', ['specify', 'clarify', 'review', 'revise']],
    ['plan', ['plan']],
    ...(drawn ? [['design', ['design']] as [string, Phase[]]] : []),
    ['tasks', ['tasks', 'map', 'analyze', 'remediate', 'checklists']],
    ['impl', ['implement', 'repair', 'converge']],
    ['verify', ['verify']],
  ]
  // A review sits in the column of what it reviews.
  const reviewed: Record<string, Phase> = { idea: 'validate', plan: 'plan', design: 'design' }
  const phase = step.phase === 'review' && step.approve ? (reviewed[step.approve.key] ?? 'review') : step.phase
  const at = order.findIndex(([, phases]) => phases.includes(phase))
  const done = snap.tasks.filter(t => t.done).length
  return order
    .map(([label], i) => {
      const extra = label === 'impl' && snap.tasks.length ? ` ${done}/${snap.tasks.length}` : ''
      return i < at ? `${label === 'spec' && unreviewed ? '◌' : '✓'}${label}` : i === at ? `▶${label}${extra}` : `·${label}`
    })
    .join(' ')
}

files.hooks/xref.ts:
// Pure X-Ref and drift logic: which task a file serves, what counts as drift, what the model is told.

import type { Anchor, Ledger, Semantic, Snapshot, Spec, Task } from '../types'
import { emptyLedger } from './ledger'
import { LADDER, isActive, isStale, levelOf } from './proof'
import type { Rung } from './proof'
import { fingerprint, isTestFile, localId, matchesAny } from './rules'
import type { Rules } from './rules'

export { emptyLedger, localId }

/** The verdicts of docs/contract-0.4.md §3, in the order they are tried. */
export type CoreVerdict = 'spec' | 'exempt' | 'task-linked' | 'planned' | 'linked' | 'unclear' | 'untracked' | 'unplanned'
export type Verdict = 'in-scope' | 'other-task' | 'linked' | 'unplanned' | 'untracked' | 'spec' | 'exempt' | 'unclear'
export type Classified = { verdict: Verdict; task: string | null }

export type Level = 'none' | 'green' | 'yellow' | 'red'
export type Finding = {
  kind: 'unplanned' | 'dangling' | 'orphan-test' | 're-verify' | 'semantic' | 'intent'
  level: 'yellow' | 'red'
  text: string
  file?: string
  intent?: string
  id?: string
}
export type Report = {
  level: Level
  findings: Finding[]
  /** Active FRs at `planned` or above. */
  covered: number
  total: number
  uncovered: string[]
  done: number
  tasks: number
  levels: Record<Rung, number>
  /** Spec gaps that do not raise the drift level. */
  notes: string[]
}

/** A text cut at a word boundary, an ellipsis where it was cut. */
export function short(text: string, max: number): string {
  if (text.length <= max) return text
  const cut = text.slice(0, max)
  const space = cut.lastIndexOf(' ')
  return (space > max * 0.5 ? cut.slice(0, space) : cut).replace(/[\s,;:(]+$/, '') + '…'
}

const MAX_UNPLANNED = 100
const MAX_INTENTS = 50

export function relPath(file: string, root: string): string {
  let path = file.replace(/\\/g, '/')
  const base = root.replace(/\\/g, '/').replace(/\/$/, '')
  if (base && path.startsWith(base + '/')) path = path.slice(base.length + 1)
  return path.replace(/^\.\//, '')
}

const basename = (path: string) => path.slice(path.lastIndexOf('/') + 1)

/** Spec Kit's own files, the design system and the agent's configuration are never drift; CI workflows are code. */
export const isSpecArtifact = (rel: string) =>
  (/^(specs|\.specify|\.claude|\.github)\//.test(rel) && !/^\.github\/workflows\//.test(rel)) || /^(CLAUDE|AGENTS|DESIGN)\.md$/.test(rel)

export function pathMatches(rel: string, planned: string): boolean {
  const p = planned.replace(/^\.\//, '')
  if (rel === p) return true
  if (p.endsWith('/')) return rel.startsWith(p)
  if (rel.endsWith('/' + p)) return true
  if (!p.includes('/') && !p.includes('.')) return false
  if (rel.startsWith(p + '/')) return true
  return !p.includes('/') && basename(rel) === p
}

/** Whether a task plans a file: a file it names always; a folder it names only while the task is open. */
export function plans(task: Task, rel: string): boolean {
  return task.paths.some(p => {
    const isFolder = p.endsWith('/') || rel.startsWith(p.replace(/^\.\//, '') + '/')
    return pathMatches(rel, p) && (!isFolder || !task.done)
  })
}

export const ANCHOR = /@spec\s+((?:[\w.-]+\/)?(?:(?:FR|SC)-\d{3,}|T-?\d{3,}|US\d+-AS\d+))/g

export function anchorsIn(text: string, file: string): Anchor[] {
  const out: Anchor[] = []
  text.split('\n').forEach((line, i) => {
    for (const m of line.matchAll(ANCHOR)) out.push({ id: m[1] ?? '', file, line: i + 1 })
  })
  return out
}

const DEFAULT_RULES: Rules = { exempt: [], unclear: [] }

/** The shared classification (§3): first match wins. The extension's batch check reports these verdicts as they are. */
export function classifyCore(
  rel: string,
  snap: Pick<Snapshot, 'tasks'>,
  ledger: Ledger,
  rules: Rules = DEFAULT_RULES,
  newText = '',
): { verdict: CoreVerdict; task: string | null } {
  if (isSpecArtifact(rel)) return { verdict: 'spec', task: null }
  if (matchesAny(rel, rules.exempt)) return { verdict: 'exempt', task: null }
  for (const [id, entry] of Object.entries(ledger.tasks)) if (entry.linked.includes(rel)) return { verdict: 'task-linked', task: id }
  // The task that plans a file comes before its anchors: it says which task the work is on.
  const matches = snap.tasks.filter(t => plans(t, rel))
  const match = matches.find(t => !t.done) ?? matches[0]
  if (match) return { verdict: 'planned', task: match.id }
  if (newText && anchorsIn(newText, rel).length > 0) return { verdict: 'linked', task: null }
  if (Object.values(ledger.requirements).some(r => r.files.includes(rel))) return { verdict: 'linked', task: null }
  if (ledger.anchors.some(a => a.file === rel)) return { verdict: 'linked', task: null }
  if (matchesAny(rel, rules.unclear)) return { verdict: 'unclear', task: null }
  if (snap.tasks.length === 0) return { verdict: 'untracked', task: null }
  return { verdict: 'unplanned', task: null }
}

/** The live verdict: a planned file is in scope for the task in focus, or moves the focus to its own task. */
export function classify(rel: string, snap: Snapshot, ledger: Ledger, active: string | null, newText = ''): Classified {
  const core = classifyCore(rel, snap, ledger, snap.rules, newText)
  switch (core.verdict) {
    case 'task-linked':
      return { verdict: 'linked', task: core.task }
    case 'planned': {
      const own = active ? snap.tasks.find(t => t.id === active && plans(t, rel)) : undefined
      if (own) return { verdict: 'in-scope', task: own.id }
      // The phase being worked on comes first: a file it shares with a later phase's task stays with this phase
      // (the mod's own rule; the shared classifyCore order is unchanged).
      const inPhase = snap.phase ? snap.tasks.filter(t => t.phase === snap.phase && plans(t, rel)) : []
      const open = inPhase.find(t => !t.done)
      if (open) return { verdict: active && open.id !== active ? 'other-task' : 'in-scope', task: open.id }
      if (inPhase.length) return { verdict: 'in-scope', task: active ?? inPhase[0]!.id }
      return { verdict: active ? 'other-task' : 'in-scope', task: core.task }
    }
    case 'linked':
    case 'unplanned':
    case 'unclear':
      return { verdict: core.verdict, task: active }
    default:
      return { verdict: core.verdict, task: null }
  }
}

/** Books one finished write into the ledger; returns the ledger it became. */
export function recordTouch(ledger: Ledger, rel: string, c: Classified, at: string): Ledger {
  const next: Ledger = { ...ledger, tasks: { ...ledger.tasks }, unplanned: ledger.unplanned }
  // Exempt and unclear files are no evidence for a task and no drift either.
  if (c.task && c.verdict !== 'unplanned' && c.verdict !== 'exempt' && c.verdict !== 'unclear') {
    const entry = next.tasks[c.task] ?? { touched: [], linked: [] }
    if (!entry.touched.includes(rel)) next.tasks[c.task] = { ...entry, touched: [...entry.touched, rel] }
  }
  if (c.verdict === 'unplanned' && !ledger.unplanned.some(u => u.file === rel && !u.acknowledged)) {
    next.unplanned = [...ledger.unplanned, { file: rel, at, task: c.task, acknowledged: false }].slice(-MAX_UNPLANNED)
  }
  return next
}

/** Ties a file to a task or requirement; a file once unplanned stops counting. */
export function link(ledger: Ledger, rel: string, id: string, snap: Snapshot, source = 'link'): { ledger: Ledger; error?: string } {
  const bare = localId(id, snap.featureDir)
  if (!bare) return { ledger, error: `${id} names another feature than ${snap.featureDir ?? 'the active one'}` }
  const next: Ledger = { ...ledger, tasks: { ...ledger.tasks }, requirements: { ...ledger.requirements } }
  if (/^T\d{3,}$/.test(bare)) {
    if (!snap.tasks.some(t => t.id === bare)) return { ledger, error: `${bare} is no task in tasks.md` }
    const entry = next.tasks[bare] ?? { touched: [], linked: [] }
    if (!entry.linked.includes(rel)) next.tasks[bare] = { ...entry, linked: [...entry.linked, rel] }
  } else if (/^(FR|SC)-\d{3,}$/.test(bare) || /^US\d+-AS\d+$/.test(bare)) {
    const known = snap.spec?.reqs.some(r => r.id === bare) || snap.spec?.stories.some(s => s.scenarios.some(x => x.id === bare))
    if (!known) return { ledger, error: `${bare} is no requirement or acceptance scenario in spec.md` }
    const entry = next.requirements[bare] ?? { tasks: [], files: [], sources: [] }
    next.requirements[bare] = {
      ...entry,
      files: entry.files.includes(rel) ? entry.files : [...entry.files, rel],
      sources: entry.sources.includes(source) ? entry.sources : [...entry.sources, source],
    }
  } else {
    return { ledger, error: `${id} is neither a task (T###), a requirement (FR-### / SC-###) nor a scenario (US1-AS1)` }
  }
  next.unplanned = ledger.unplanned.map(u => (u.file === rel ? { ...u, acknowledged: true } : u))
  // The text a link was made against: when it changes, the link needs new proof.
  const req = snap.spec?.reqs.find(r => r.id === bare)
  if (req) next.fingerprints = { ...ledger.fingerprints, [bare]: fingerprint(req.text) }
  return { ledger: next }
}

export function logIntent(ledger: Ledger, text: string, task: string | null, at: string): Ledger {
  return { ...ledger, intents: [...ledger.intents, { at, text: text.slice(0, 500), task, status: 'logged' as const }].slice(-MAX_INTENTS) }
}

export function acknowledgeAll(ledger: Ledger): Ledger {
  return { ...ledger, unplanned: ledger.unplanned.map(u => ({ ...u, acknowledged: true })) }
}

/** Whether a logged prompt and a change the check quoted from it are the same request. */
const quotes = (logged: string, quoted: string) => logged.includes(quoted) || quoted.includes(logged.slice(0, 40))

export function resolveIntent(ledger: Ledger, text: string): Ledger {
  const semantic = ledger.semantic ? { ...ledger.semantic, changes: ledger.semantic.changes.filter(c => c.text !== text) } : null
  return { ...ledger, semantic, intents: ledger.intents.map(i => (i.status !== 'resolved' && quotes(i.text, text) ? { ...i, status: 'resolved' as const } : i)) }
}

/** The task in focus while it is open; once it is checked off, the first open one. */
export function currentTask(snap: Snapshot, active: string | null): Task | null {
  const chosen = active ? snap.tasks.find(t => t.id === active && !t.done) : undefined
  return chosen ?? snap.tasks.find(t => !t.done) ?? null
}

/** The edits outside the plan still open. Rules apply to what was booked before they changed: a file now exempt or unclear is no drift any more. */
export function openUnplanned(snap: Pick<Snapshot, 'rules'>, ledger: Ledger) {
  const quiet = [...(snap.rules?.exempt ?? []), ...(snap.rules?.unclear ?? [])]
  return ledger.unplanned.filter(u => !u.acknowledged && !matchesAny(u.file, quiet))
}

/** What the ladder reads from a snapshot. */
const proofSnap = (snap: Snapshot) => ({ featureDir: snap.featureDir, tasks: snap.tasks, reqs: snap.spec?.reqs ?? [], realTests: snap.realTests ?? [] })

/**
 * The drift report (§8). Only deterministic findings decide unless `semantic` is on: the live mod lets the
 * intent check count, the extension's exit code never does.
 */
export function evaluate(snap: Snapshot, ledger: Ledger, opts: { semantic?: boolean } = {}): Report {
  const semanticOn = opts.semantic ?? true
  const findings: Finding[] = []
  const open = openUnplanned(snap, ledger)
  for (const u of open) findings.push({ kind: 'unplanned', level: 'yellow', file: u.file, text: `${u.file} is not planned for any task` })
  if (open.length >= 3) findings.push({ kind: 'unplanned', level: 'red', text: `${open.length} edits outside the planned files` })

  const reqs = snap.spec?.reqs ?? []
  const byId = new Map(reqs.map(r => [r.id, r]))
  const known = new Set([...reqs.filter(r => isActive(r)).map(r => r.id), ...snap.tasks.map(t => t.id), ...(snap.spec?.stories.flatMap(s => s.scenarios.map(x => x.id)) ?? [])])
  for (const a of ledger.anchors) {
    const bare = localId(a.id, snap.featureDir)
    if (!bare || known.has(bare)) continue
    const old = byId.get(bare)
    const why = old ? (old.supersededBy ? `superseded by ${old.supersededBy}` : 'retired') : 'which the spec no longer has'
    const test = isTestFile(a.file)
    findings.push({
      kind: test ? 'orphan-test' : 'dangling',
      level: 'yellow',
      file: a.file,
      id: bare,
      text: test ? `${a.file}:${a.line} tests ${a.id}, ${old ? `which is ${why}` : why}` : `${a.file}:${a.line} anchors ${a.id}, ${old ? `which is ${why}` : why}`,
    })
  }
  const proof = proofSnap(snap)
  for (const r of reqs) {
    if (isActive(r) && isStale(r.id, proof, ledger)) findings.push({ kind: 're-verify', level: 'yellow', id: r.id, text: `${r.id} changed since it was last proven; it needs new proof` })
  }

  const s = ledger.semantic
  if (s && semanticOn) {
    if (s.verdict === 'drift' || s.score < 50) findings.push({ kind: 'semantic', level: 'red', text: `Intent check ${s.score}/100: ${s.reasons[0] ?? 'the change drifts from the spec'}` })
    else if (s.verdict === 'minor' || s.score < 80) findings.push({ kind: 'semantic', level: 'yellow', text: `Intent check ${s.score}/100: ${s.reasons[0] ?? 'minor drift'}` })
    for (const c of s.changes) {
      findings.push({ kind: 'intent', level: c.kind === 'contradicts' ? 'red' : 'yellow', intent: c.text, text: `User asked: "${c.text}", ${c.kind === 'contradicts' ? 'which contradicts the spec' : 'which the spec does not cover'}` })
    }
  }

  const frs = reqs.filter(r => r.kind === 'FR' && isActive(r))
  const levels = Object.fromEntries(LADDER.map(r => [r, 0])) as Record<Rung, number>
  const uncovered: string[] = []
  for (const r of frs) {
    const rung = levelOf(r.id, proof, ledger)
    levels[rung] += 1
    if (rung === 'specified') uncovered.push(r.id)
  }
  const notes = (snap.spec?.stories ?? []).filter(st => st.scenarios.length === 0).map(st => `${st.id} has no acceptance scenarios`)
  const level: Level = !snap.featureDir ? 'none' : findings.some(f => f.level === 'red') ? 'red' : findings.length ? 'yellow' : 'green'
  return {
    level,
    findings,
    covered: frs.length - uncovered.length,
    total: frs.length,
    uncovered,
    done: snap.tasks.filter(t => t.done).length,
    tasks: snap.tasks.length,
    levels,
    notes,
  }
}

/** The FRs a task serves: named in its text, or mapped to it in the ledger. */
export function reqsOf(task: Task, ledger: Ledger): string[] {
  const mapped = Object.entries(ledger.requirements).filter(([, r]) => r.tasks.includes(task.id)).map(([id]) => id)
  return [...new Set([...task.reqs, ...mapped])]
}

/** How the project invokes a Spec Kit command: `xref.map` is `/speckit-xref-map` for skills, `/speckit.xref.map` for commands. */
export const speckitCommand = (snap: Snapshot, name: string) =>
  snap.commandStyle === 'skills' ? `/speckit-${name.replace(/\./g, '-')}` : `/speckit.${name}`

/**
 * The system prompt section: the active spec and the rules that keep the work on it.
 * It changes only when the spec does, so the conversation's prompt cache survives task switches;
 * the current task and the drift status ride each prompt instead (turnContext).
 */
export function composeSection(snap: Snapshot, mode: string, plugin: string): string | null {
  if (!snap.featureDir || !snap.spec) return null
  const spec = snap.spec
  const lines: string[] = [
    '# Spec Kit cross-reference (speckit-xref)',
    'This repository follows GitHub Spec Kit. Keep the work inside the active spec and say so when it would leave it.',
    '',
    `Active feature: ${snap.featureDir} — ${spec.title}`,
  ]
  if (spec.input) lines.push(`The user's original words: "${spec.input}"`)
  if (spec.stories.length) lines.push(`User stories: ${spec.stories.map(s => `${s.id}${s.priority ? ` (${s.priority})` : ''} ${s.title}`).join(' | ')}`)
  if (snap.constitution?.musts.length) lines.push('Constitution, MUST rules:', ...snap.constitution.musts.slice(0, 8).map(m => `- ${m}`))
  if (spec.outOfScope.length) lines.push('Out of scope:', ...spec.outOfScope.map(o => `- ${o}`))
  const clar = spec.reqs.filter(r => r.needsClarification).map(r => r.id)
  if (clar.length) lines.push(`Still marked NEEDS CLARIFICATION: ${clar.join(', ')}. Ask the user before implementing them.`)
  lines.push(
    '',
    'Rules:',
    `- Before editing a file the current task does not plan, name the task or requirement it serves; call mcp__${plugin}__focus to switch tasks or mcp__${plugin}__link to tie the file to one.`,
    `- When the user asks for something the spec does not cover or contradicts, say so plainly and offer to update the spec (${speckitCommand(snap, 'clarify')}) before building it.`,
    '- Check a task off in tasks.md ([X]) only once the requirements it serves are met.',
    `- Mark code that implements a requirement with a comment at file or function level: @spec ${basename(snap.featureDir)}/FR-###.`,
    '- Each user prompt carries a "speckit-xref" note with the current task and the drift status; follow it.',
  )
  if (mode === 'strict') lines.push("- Strict mode: edits outside the current task's planned or linked files are refused until you focus another task or link the file.")
  return lines.join('\n')
}

/** The note beside a user's prompt: the current task, what it serves, and the drift status right now. */
export function turnContext(snap: Snapshot, ledger: Ledger, active: string | null, next?: string): string | null {
  if (!snap.featureDir || !snap.spec) return null
  const report = evaluate(snap, ledger)
  const task = currentTask(snap, active)
  const lines = [`speckit-xref · ${snap.featureDir} · tasks ${report.done}/${report.tasks} · FR covered ${report.covered}/${report.total} · drift ${report.level}`]
  if (task) {
    lines.push(`Current task: ${task.id}${task.story ? ` [${task.story}]` : ''} ${task.text}`)
    if (task.paths.length) lines.push(`Planned files: ${task.paths.join(', ')}`)
    const reqs = reqsOf(task, ledger)
    if (reqs.length) {
      const byId = new Map(snap.spec.reqs.map(r => [r.id, r.text]))
      lines.push('Serves:', ...reqs.map(id => `- ${id}: ${byId.get(id) ?? ''}`))
    }
    const next = snap.tasks.filter(t => !t.done && t.id !== task.id).slice(0, 3)
    if (next.length) lines.push(`Next: ${next.map(t => `${t.id} ${short(t.text, 80)}`).join(' | ')}`)
  } else if (snap.tasks.length === 0) {
    lines.push(`No tasks.md yet; ${speckitCommand(snap, 'tasks')} derives them from the plan.`)
  } else {
    lines.push('Every task in tasks.md is checked.')
  }
  if (report.findings.length) lines.push('Drift:', ...report.findings.slice(0, 5).map(f => `- ${f.text}`))
  if (next) lines.push(`Next Spec Kit step: ${next}`)
  return lines.join('\n')
}

/** What the model reads beside a write's result when the write left the plan, or moved to another task. */
export function editNote(rel: string, c: Classified, snap: Snapshot, previous: string | null, plugin: string): string | null {
  if (c.verdict === 'unplanned') {
    const task = currentTask(snap, previous)
    const planned = task?.paths.length ? ` (it plans ${task.paths.join(', ')})` : ''
    return `speckit-xref: ${rel} is not planned for ${task ? `the current task ${task.id}${planned}` : 'any task'}. If it serves the spec, call mcp__${plugin}__link with the task or requirement; if the user asked for it beyond the spec, tell them and offer ${speckitCommand(snap, 'clarify')}.`
  }
  if (c.verdict === 'other-task' && c.task && c.task !== previous) {
    const task = snap.tasks.find(t => t.id === c.task)
    if (task?.done) return `speckit-xref: ${rel} belongs to ${c.task}, which is checked off: this is rework on a finished task.`
    return `speckit-xref: ${rel} belongs to ${c.task}${task ? ` (${task.text.slice(0, 80)})` : ''}; that is now the current task.`
  }
  return null
}

/** The question the drift check asks over the session's own transcript. */
export function forkPrompt(snap: Snapshot, ledger: Ledger, active: string | null, changed: string[], diff: string, withLog = false): string {
  const spec = snap.spec
  // Without the transcript (a check run before the session's first turn) the logged prompts stand in for the user's words.
  const said = withLog ? ledger.intents.filter(i => i.status !== 'resolved').slice(-10).map(i => `- ${i.text}`) : []
  const task = currentTask(snap, active)
  const reqs = spec?.reqs.map(r => `${r.id}: ${r.text}`).join('\n') ?? '(no spec)'
  return [
    'You are auditing this session for drift. Do not call any tool. Answer with ONE JSON object and nothing else.',
    'Compare (1) what the user asked for in this conversation, in their own words, (2) the active Spec Kit spec below, and (3) the files changed in the last turn.',
    '',
    `Spec: ${spec?.title ?? '-'} (${snap.featureDir ?? '-'})`,
    `Original request: ${spec?.input ?? '-'}`,
    `Requirements:\n${reqs}`,
    `Out of scope: ${spec?.outOfScope.join('; ') || '-'}`,
    `Current task: ${task ? `${task.id} ${task.text}` : '-'}`,
    ...(ledger.decisions.some(d => d.answer)
      ? ['Decisions the person already made (settled: never an intent change):', ...ledger.decisions.filter(d => d.answer).slice(-8).map(d => `- ${d.question} → ${d.answer}`)]
      : []),
    ...(said.length ? ['What the user said in this session, oldest first:', ...said] : []),
    `Changed files: ${changed.join(', ') || '-'}`,
    `Diff (may be cut):\n${diff.slice(0, 6000) || '(no diff available)'}`,
    '',
    'JSON shape: {"score": 0-100 (100 = the change matches both the user\'s intent and the spec), "verdict": "aligned" | "minor" | "drift", "reasons": ["at most 3 short reasons"], "intent_changes": [{"text": "a short quote of something the user asked for during the session that the spec does not cover or contradicts", "kind": "extends" | "contradicts"}]}',
    'intent_changes holds only requests the user made, never the spec\'s own text; code that contradicts the spec without the user asking for it belongs in reasons and the score. An empty list is the normal answer.',
  ].join('\n')
}

/** The first JSON object in a model reply. */
function firstJson(text: string): unknown {
  const start = text.indexOf('{')
  const end = text.lastIndexOf('}')
  if (start === -1 || end <= start) return null
  try {
    return JSON.parse(text.slice(start, end + 1))
  } catch {
    return null
  }
}

export function parseSemantic(text: string, at: string): Semantic | null {
  const raw = firstJson(text) as Record<string, unknown> | null
  if (!raw || typeof raw.score !== 'number') return null
  const verdict = raw.verdict === 'aligned' || raw.verdict === 'minor' || raw.verdict === 'drift' ? raw.verdict : raw.score >= 80 ? 'aligned' : raw.score >= 50 ? 'minor' : 'drift'
  const reasons = Array.isArray(raw.reasons) ? raw.reasons.filter((r): r is string => typeof r === 'string').slice(0, 3) : []
  const changes = Array.isArray(raw.intent_changes)
    ? raw.intent_changes
        .filter((c): c is { text: string; kind?: string } => !!c && typeof (c as { text?: unknown }).text === 'string')
        .map(c => ({ text: c.text.slice(0, 200), kind: c.kind === 'contradicts' ? ('contradicts' as const) : ('extends' as const) }))
        .slice(0, 5)
    : []
  return { score: Math.max(0, Math.min(100, Math.round(raw.score))), verdict, reasons, changes, at }
}

export function applySemantic(ledger: Ledger, semantic: Semantic): Ledger {
  // A change the user already resolved stays resolved when a later check quotes it again.
  const resolved = ledger.intents.filter(i => i.status === 'resolved')
  const changes = semantic.changes.filter(c => !resolved.some(i => quotes(i.text, c.text)))
  const intents = ledger.intents.map(i => {
    const hit = changes.find(c => i.status === 'logged' && quotes(i.text, c.text))
    return hit ? { ...i, status: hit.kind } : i
  })
  return { ...ledger, intents, semantic: { ...semantic, changes } }
}

export function mapPrompt(spec: Spec, tasks: Task[]): string {
  return [
    'Map each functional requirement of a Spec Kit feature to the tasks that implement it. Answer with ONE JSON object and nothing else:',
    '{"FR-001": ["T004", "T005"], ...}. Use only ids listed below; a requirement no task serves maps to [].',
    '',
    'Requirements:',
    ...spec.reqs.filter(r => r.kind === 'FR').map(r => `${r.id}: ${r.text}`),
    '',
    'Tasks:',
    ...tasks.map(t => `${t.id}${t.story ? ` [${t.story}]` : ''}: ${t.text}`),
  ].join('\n')
}

export function applyMapping(ledger: Ledger, text: string, snap: Snapshot): { ledger: Ledger; mapped: number } {
  const raw = firstJson(text) as Record<string, unknown> | null
  if (!raw) return { ledger, mapped: 0 }
  const reqIds = new Set(snap.spec?.reqs.map(r => r.id) ?? [])
  const taskIds = new Set(snap.tasks.map(t => t.id))
  const requirements = { ...ledger.requirements }
  const fingerprints = { ...ledger.fingerprints }
  let mapped = 0
  for (const [id, value] of Object.entries(raw)) {
    if (!reqIds.has(id) || !Array.isArray(value)) continue
    const tasks = value.filter((t): t is string => typeof t === 'string' && taskIds.has(t))
    const entry = requirements[id] ?? { tasks: [], files: [], sources: [] }
    requirements[id] = { ...entry, tasks: [...new Set([...entry.tasks, ...tasks])], sources: entry.sources.includes('llm') ? entry.sources : [...entry.sources, 'llm'] }
    if (tasks.length) {
      mapped += 1
      const req = snap.spec?.reqs.find(r => r.id === id)
      if (req) fingerprints[id] = fingerprint(req.text)
    }
  }
  return { ledger: { ...ledger, requirements, fingerprints }, mapped }
}

export const REMEDIATION_HEADING = '## Drift Remediation (speckit-xref)'

/** tasks.md with one more open task under the remediation heading, numbered after the highest T###. */
export function appendRemediation(tasksMd: string, tasks: Task[], text: string): { markdown: string; id: string } {
  const highest = tasks.reduce((max, t) => Math.max(max, Number(t.id.slice(1)) || 0), 0)
  const width = Math.max(3, tasks[0]?.id.length ? tasks[0].id.length - 1 : 3)
  const id = 'T' + String(highest + 1).padStart(width, '0')
  const line = `- [ ] ${id} [Drift] ${text.replace(/\s+/g, ' ').trim()}`
  const base = tasksMd.replace(/\s*$/, '')
  const markdown = base.includes(REMEDIATION_HEADING) ? `${base}\n${line}\n` : `${base}\n\n${REMEDIATION_HEADING}\n\n${line}\n`
  return { markdown, id }
}

